window.DICTIONARY_ENTRY_SHARDS["0067-0068"]={"0067-0068:046b32891f59e4":{"word":"GHB","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"GHB","de-DE":"GHB"},"forms":[],"senses":[{"definition":"Abkürzung für Gamma-Hydroxy-Butansäure"},{"definition":"Abkürzung für Gamma-Hydroxy-Buttersäure"},{"definition":"Abkürzung für Gamma-Hydroxy-Butyrat"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"GHB","id":"046b32891f59e4"},"0067-0068:8fc81540ce39e1":{"word":"ghanaisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"gha·na·isch","de-DE":"gha·na·isch"},"forms":[{"form":"ghanaisch","tags":["Positiv"]},{"form":"ghanaische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"ghanaischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"ghanaischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"ghanaischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"ghanaisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"ghanaischere","tags":["Komparativ","Nominativ","strong","Singular","feminine"]},{"form":"ghanaischste","tags":["Superlativ","Nominativ","strong","Singular","feminine"]},{"form":"ghanaischerem","tags":["Komparativ","Dativ","strong","Singular","masculine"]},{"form":"ghanaischeren","tags":["Komparativ","Genitiv","strong","Singular","masculine"]},{"form":"ghanaischerer","tags":["Komparativ","Nominativ","strong","Singular","masculine"]},{"form":"ghanaischeres","tags":["Komparativ","Nominativ","strong","Singular","neuter"]},{"form":"ghanaischstem","tags":["Superlativ","Dativ","strong","Singular","masculine"]},{"form":"ghanaischsten","tags":["Superlativ","Genitiv","strong","Singular","masculine"]},{"form":"ghanaischster","tags":["Superlativ","Nominativ","strong","Singular","masculine"]},{"form":"ghanaischstes","tags":["Superlativ","Nominativ","strong","Singular","neuter"]},{"form":"er ist ghanaisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist ghanaisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist ghanaisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"er ist ghanaischer","tags":["Komparativ","predicative","Singular","masculine"]},{"form":"es ist ghanaischer","tags":["Komparativ","predicative","Singular","neuter"]},{"form":"sie sind ghanaisch","tags":["Positiv","predicative","Plural"]},{"form":"sie ist ghanaischer","tags":["Komparativ","predicative","Singular","feminine"]},{"form":"sie sind ghanaischer","tags":["Komparativ","predicative","Plural"]},{"form":"er ist am ghanaischsten","tags":["Superlativ","predicative","Singular","masculine"]},{"form":"es ist am ghanaischsten","tags":["Superlativ","predicative","Singular","neuter"]},{"form":"sie ist am ghanaischsten","tags":["Superlativ","predicative","Singular","feminine"]},{"form":"sie sind am ghanaischsten","tags":["Superlativ","predicative","Plural"]}],"senses":[{"definition":"Ghana betreffend, aus Ghana kommend"}],"synonyms":[],"origins":["Derivation des Substantivs Ghana mit dem Suffix -isch"],"examples":[{"text":"„Der ghanaische Staatspräsident John Atta Mills ist gestorben.“","reference":"Ghanas Staatspräsident Mills gestorben. In: Spiegel Online. 24. Juli 2012, ISSN 0038-7452 (URL, abgerufen am 10. April 2014) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"ghanaisch","id":"8fc81540ce39e1"},"0067-0068:963b8d724718d3":{"word":"Ghanaer","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Gha·na·er","de-DE":"Gha·na·er"},"forms":[{"form":"Ghanaer","tags":["Nominativ","Singular"]},{"form":"Ghanaern","tags":["Dativ","Plural"]},{"form":"Ghanaers","tags":["Genitiv","Singular"]},{"form":"Ghanaerin","tags":["feminine"]}],"senses":[{"definition":"Staatsbürger von Ghana"}],"synonyms":[],"origins":[],"examples":[{"text":"Herr Lohse arbeitet auf der Farm eines Ghanaers.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghanaer","id":"963b8d724718d3"},"0067-0068:cc584cd530348f":{"word":"Ghanaerin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Gha·nae·rin","de-DE":"Gha·nae·rin"},"forms":[{"form":"Ghanaer","tags":["masculine"]},{"form":"Ghanaerin","tags":["Nominativ","Singular"]},{"form":"Ghanaerinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Staatsbürgerin von Ghana"}],"synonyms":[],"origins":[],"examples":[{"text":"Im Hotel haben sich vier Ghanaerinnen ein Zimmer genommen.","reference":""},{"text":"Der Chef ist mit einer Ghanaerin verheiratet.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghanaerin","id":"cc584cd530348f"},"0067-0068:65368c4fecc050":{"word":"Ghanese","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Gha·ne·se","de-DE":"Gha·ne·se"},"forms":[{"form":"Ghanese","tags":["Nominativ","Singular"]},{"form":"Ghanesen","tags":["Nominativ","Plural"]},{"form":"Ghanesin","tags":["feminine"]}],"senses":[{"definition":"Staatsbürger von Ghana"}],"synonyms":[],"origins":["Ableitung von Ghana"],"examples":[{"text":"„Der Ghanese strahlt nicht gerade vor Begeisterung, als John ihn bittet, mich in die Lodge zu bringen.“","reference":"Manfred Elbern: Die Inseln der Liebe. Ein Reisebericht aus dem Südpazifik. Books on Demand Gmbh, 1999, ISBN 3898110133, Seite 112"},{"text":"„Der 31-jährige Ghanese, der die Schweizer Bank UBS um mindestens 2,3 Milliarden Dollar brachte, wird von Kollegen und Freunden als hochbegabt, freundlich, ja charismatisch beschrieben.“","reference":"Aus der Krise nichts gelernt. In: Zeit Online. 19. September 2011, ISSN 0044-2070 (URL, abgerufen am 24. November 2022) ."},{"text":"„Obwohl Ghana zu den sichersten und stabilsten Ländern in ganz Afrika zählt, die Sterblichkeitsrate ist hoch, der Altersdurchschnitt schockierend niedrig. Nahezu zwei Drittel aller Ghanesen sind unter 15 Jahren.“","reference":"Die Lernwütigen. In: Spiegel Online. 13. Dezember 2004, ISSN 0038-7452 (URL, abgerufen am 24. November 2022) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghanese","id":"65368c4fecc050"},"0067-0068:d6d6276be9d20c":{"word":"Ghanesin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Gha·ne·sin","de-DE":"Gha·ne·sin"},"forms":[{"form":"Ghanese","tags":["masculine"]},{"form":"Ghanesin","tags":["Nominativ","Singular"]},{"form":"Ghanesinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Staatsbürgerin von Ghana"}],"synonyms":[],"origins":[],"examples":[{"text":"„Er glaubt, seine verschwundene Ghanesin habe seine Verfolger auf ihn gehetzt, er nimmt es als Zeichen ihres nicht erloschenen Interesses an ihm.“","reference":"Irmgard B. Perfahl: Mosaik, Tübingen 1994, S. 18"},{"text":"„Da kommt ein bolivianisch-holländischer Junge zur Welt, sprüht ein chinesisches Feuerwerk, begutachtet eine Ghanesin beim Nigerianer Stoffe.“","reference":"Weltonline: „Filmemacher Johan van der Keuken gestorben“, 11.01.2001"},{"text":"„Nur Sally, eine Ghanesin, die er 1961 heiratete, und vermutlich die einzige Frau, die er liebte, befreite ihn aus einer tief empfundenen sozialen Isolation.“","reference":"Markus M. Haeflinger: „Das lange Scheitern Robert Mugabes, der es recht machen wollte“, 13. April 2008"},{"text":"„Den Anfang machte am 22. November die Ghanesin Mavis, die seit einigen Jahren in Leibnitz lebt und in traditioneller Kleidung erschienen ist.“","reference":"„Steirische Gemeindenachrichten“, S. 13, Februar 2007"},{"text":"„Den 100-m-Lauf der Frauen entschied die Ghanesin Tahesia Harrigan bei leichtem Rückenwind in ansprechenden 11,25 für sich.“","reference":"Schweizer Fernsehen: „Dreispringer Martinez mit Rekord und EM-Limite“, 6. Juli 2006"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghanesin","id":"d6d6276be9d20c"},"0067-0068:adb778cff75308":{"word":"Ghana","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Gha·na","de-DE":"Gha·na"},"forms":[{"form":"GH","tags":["Kurzform"]},{"form":"GHA","tags":["Kurzform"]},{"form":"Ghanas","tags":["Genitiv","Singular"]},{"form":"des Ghana","tags":["Genitiv","Singular"]},{"form":"des Ghanas","tags":["Genitiv","Singular"]},{"form":"(das) Ghana","tags":["Nominativ","Singular"]},{"form":"(dem) Ghana","tags":["Dativ","Singular"]}],"senses":[{"definition":"Staat in Westafrika"}],"synonyms":["Goldküste","Republik Ghana"],"origins":[],"examples":[{"text":"Er sagt, er komme aus Ghana.","reference":""},{"text":"Accra ist die Hauptstadt von Ghana.","reference":""},{"text":"„Wirtschaftlich bedeutend ist Ghana aufgrund seines Rohstoffreichtums.“","reference":"Wikipedia-Artikel „Ghana“"}],"idioms":[],"collocations":[],"derivations":["ghanaisch","Ghanaer","Ghanaerin","Ghanese","Ghanesin"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ghana","id":"adb778cff75308"},"0067-0068:a49ca0b64946c5":{"word":"Ghetto","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ghet·to","de-DE":"Ghet·to"},"forms":[{"form":"Getto","tags":["alternative"]},{"form":"Ghetti","tags":["Nominativ","Plural"]},{"form":"Ghetto","tags":["Nominativ","Singular"]},{"form":"Ghettos","tags":["Nominativ","Plural"]}],"senses":[{"definition":"von der jüdischen Bevölkerung (anfänglich freiwillig, später zwangsweise) bewohntes, von den übrigen Stadtvierteln (durch Mauern oder Ähnliches) abgetrenntes Viertel"},{"definition":"(militärisch streng bewachtes) isoliertes Stadtviertel, in dem die jüdische Bevölkerung gezwungenermaßen abgesondert von der übrigen Stadtbevölkerung (in unmenschlichen Lebensverhältnissen) leben musste"},{"definition":"von diskriminierten Minderheiten, Ausländern oder auch privilegierten Bevölkerungsgruppen bewohnter Bezirk beziehungsweise Viertel einer Stadt"},{"definition":"bestimmte (soziale, wirtschaftliche oder dergleichen) mentale oder psychische Sphäre, der sich jemand nicht entziehen kann"}],"synonyms":["Armenviertel","Bidonville","Bronx","Elendsviertel","Favela","Gecekondu","Getto","informelle Siedlung","Marginalsiedlung","Pennerbezirk","Slum"],"origins":[],"examples":[{"text":"„Der Ghetto also liegt an eben jener Halle der Oktavia, wo Vespasian und Titus den Triumph über die Juden einweihten, und um diesen jetzt im Schmutz starrenden Portikus wohnen heute Nachkommen jener Hebräer, die damals Kriegssklaven des Titus waren.“","reference":"Ferdinand Gregorovius ^(→ WP): Wanderjahre in Italien. In: Projekt Gutenberg-DE. Der Ghetto und die Juden in Rom 1853 (URL) . Alte Version im Internet-Archiv abrufbar. *"},{"text":"„Wegen der historischen Beziehung des Volkes Israel zu den Römern, welche Jerusalem zerstörten und das Judenvolk in die Welt zerstreuten, ist der Ghetto Roms unter allen Judengemeinden Europas die merkwürdigste.“","reference":""},{"text":"„Die Vorgänge in Ländern, die noch gar nicht entdeckt waren, als Europa die Juden in Ghetti sperrte, sind uns in der nächsten Stunde bekannt.“","reference":"Theodor Herzl ^(→ WP): Der Judenstaat. In: Projekt Gutenberg-DE. Einleitung (URL) . Alte Version im Internet-Archiv abrufbar. *"},{"text":"„Das gewöhnliche Volk hat kein historisches Verständnis und kann keines haben. Es weiß nicht, daß die Sünden des Mittelalters jetzt an den europäischen Völkern heimkommen. Wir sind, wozu man uns in den Ghetti gemacht hat.“","reference":"Theodor Herzl ^(→ WP): Der Judenstaat. In: Projekt Gutenberg-DE. Allgemeiner Teil; Die Judenfrage (URL) . Alte Version im Internet-Archiv abrufbar. *"},{"text":"„Zwei Jahre später bereiste er den nordostpolnischen Bezirk Bialystok und begrüßte hinterher, daß die ‚Juden nur noch in den Ghetti der Städte anzutreffen‘ seien.“","reference":"Zeitgeschichte: Dienstbare Geister. In: DER SPIEGEL. Nummer 39/1998, 21. September 1998, ISSN 0038-7452, Seite 107 (DER SPIEGEL Archiv-URL, abgerufen am 8. Januar 2014) ."},{"text":"„So hatte Roman vom Aufstand im Warschauer Ghetto erfahren, etwa eine Woche nach Ausbruch, gegen Ende April, über Radio London.“","reference":"Ralph Giordano: Die Bertinis. Roman. 22. Auflage. Fischer Taschenbuch Verlag, Frankfurt/M. 2008, ISBN 978-3-596-25961-8, Seite 320 ."},{"text":"„Hermann Adler hat die Hölle überlebt – die Ghettos von Wilna und Warschau, das KZ Bergen-Belsen.“","reference":"Jürgen Serke: Die verbrannten Dichter. Lebensgeschichten und Dokumente. 2. Auflage. Wallstein, Göttingen 2023, ISBN 978-3-8353-5388-6, Seite 273."},{"text":"„Seine Eltern haben in Wien gelebt und sind ins Ghetto von Lodz deportiert worden.“","reference":"Anatol Regnier: Jeder schreibt für sich allein. Schriftsteller im Nationalsozialismus. 2. Auflage. btb, München 2022, ISBN 978-3-442-77183-7, Seite 246. 1. Auflage 2022."},{"text":"„Aber es ist kein Ghetto der Jugendlichkeit und Radikalität entstanden.“","reference":"Stephan Wackwitz: Osterweiterung. Zwölf Reisen. Fischer Taschenbuch Verlag, Frankfurt/Main 2010, ISBN 978-3-596-17459-1 , Seite 112."}],"idioms":[],"collocations":[],"derivations":["Ghettoaufstand","Ghettobewohner","Ghettobildung","Ghettoblaster","Ghettoinsasse","ghettoisieren","Ghettoisierung","Ghetto-Jugend","Ghetto-Kid","Ghettokind","Ghettonovelle","Ghettopolizei","Ghettopolizist"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ghetto","id":"a49ca0b64946c5"},"0067-0068:b08a0ba1e9b804":{"word":"Ghostwriter","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ghost·wri·ter","de-DE":"Ghost·wri·ter"},"forms":[{"form":"Ghostwriter","tags":["Nominativ","Singular"]},{"form":"Ghostwritern","tags":["Dativ","Plural"]},{"form":"Ghostwriters","tags":["Genitiv","Singular"]},{"form":"Ghostwriterin","tags":["feminine"]}],"senses":[{"definition":"Person, die für jemand anderen Texte verfasst, aber als Autor nicht genannt wird"}],"synonyms":["Auftragsschreiber","Lohnschreiber","Phantomschreiber"],"origins":["von gleichbedeutend englisch ghost writer ^(→ en)"],"examples":[{"text":"„Es gibt weiterhin den Verdacht, dass er die Arbeit nicht selbst verfasst hat, dass es einen Ghostwriter gab.“","reference":"Thomas Darnstädt und andere: Doktor der Reserve. In: DER SPIEGEL. Nummer 8, 2011 . Seite 20-29, Zitat Seite 21."},{"text":"„Mein einstiger Dozent scheint sich hingegen leergeschrieben zu haben, sonst hätte er mich nicht als Ghostwriter in Dienst gestellt.“","reference":"Günter Grass: Im Krebsgang. Eine Novelle. Steidl, Göttingen 2002, ISBN 3-88243-800-2, Seite 30."},{"text":"„Bevor ich antworten konnte, fragte er mich, womit ich jetzt mein Geld verdiene, und ich erzählte ihm von meinen Aufträgen als Ghostwriterin eines Ghostwriters.“","reference":"Nava Ebrahimi: Sechzehn Wörter. Roman. btb, München 2019, ISBN 978-3-442-71754-5 , Seite 169."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ghostwriter","id":"b08a0ba1e9b804"},"0067-0068:6968769b7edd41":{"word":"Ghettoblaster","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ghet·to·blas·ter","de-DE":"Ghet·to·blas·ter"},"forms":[{"form":"Gettoblaster","tags":["alternative"]},{"form":"Ghettoblaster","tags":["Nominativ","Singular"]},{"form":"Ghettoblastern","tags":["Dativ","Plural"]},{"form":"Ghettoblasters","tags":["Genitiv","Singular"]}],"senses":[{"definition":"großer, portabler Radiorekorder mit leistungsstarken Verstärkern"}],"synonyms":["Boombox"],"origins":[],"examples":[{"text":"„Ein junger Mann mit E-Gitarre und einem kleinen Ghettoblaster singt Popsongs, um 23 Uhr, mitten in der fast menschenleeren Fußgängerzone.“","reference":"Patrizia Schlosser: Schuhplattler und Garagenrock. In: Der Spiegel (Online-Ausgabe). Abgerufen am 1. August 2011."},{"text":"„Der Meister wirkte beim Anblick seines Ghettoblasters aufgedreht wie ein Kind.“","reference":"Radek Knapp: Gebrauchsanweisung für Polen. 5. Auflage. Piper, München, Zürich 2011 , Seite 151. ISBN 978-3-492-27536-1."},{"text":"„Unweit davon versammelten sich Mädchen im Teenageralter um einen Ghettoblaster und führten einen hüftbetonten Tanz auf, der dem im Captain Bligh Restaurant sehr nahe kam.“","reference":"Tony Horwitz: Cook. Die Entdeckung eines Entdeckers. Piper, München/Zürich 2006 (übersetzt von Heike Steffen), ISBN 978-3-492-24473-2 , Seite 113. Englisches Original 2002."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ghettoblaster","id":"6968769b7edd41"},"0067-0068:3922b6ddefd8f9":{"word":"Ghettoisierung","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ghet·toi·sie·rung","de-DE":"Ghet·toi·sie·rung"},"forms":[{"form":"Gettoisierung","tags":["alternative"]},{"form":"Ghettoisierung","tags":["Nominativ","Singular"]},{"form":"Ghettoisierungen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"zunehmende Isolierung, zunehmende Bildung von Gettos"}],"synonyms":["(das) Herunterkommen","Verslumung"],"origins":[],"examples":[{"text":"„Die Intensität der Massaker war wie die Ghettoisierung regional unterschiedlich.“","reference":"Saul Friedländer: Das Dritte Reich und die Juden. Die Jahre der Vernichtung 1939 — 1945. 2, C.H. Beck, München 2006 (Originaltitel: Nazi Germany and the Jews, übersetzt von Martin Pfeiffer), ISBN 3406549667 , Seite 237."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ghettoisierung","id":"3922b6ddefd8f9"},"0067-0068:30daa913e88ea6":{"word":"Ghasel","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Gha·sel","de-DE":"Gha·sel"},"forms":[{"form":"Ghasel","tags":["Nominativ","Singular"]},{"form":"Ghasele","tags":["Nominativ","Plural"]},{"form":"Ghasels","tags":["Genitiv","Singular"]},{"form":"Ghaselen","tags":["Dativ","Plural"]}],"senses":[{"definition":"arabische Form lyrischer Dichtung nach dem Reimschema aa, ba, ca"}],"synonyms":[],"origins":[],"examples":[{"text":"„Ich umarmte meine Mutter, aber ich erzählte ihr nichts von dem, was mir begegnet war, denn ich hatte in unseren Ghaselen gelesen, daß die Feen es lieben, wenn man ihr Geheimnis bewahrt.“","reference":"Jan Graf Potocki: Die Handschrift von Saragossa oder Die Abenteuer in der Sierra Morena. Roman. Gerd Haffmans bei Zweitausendeins, Frankfurt/Main 2003, Seite 814. Übersetzung von 1962 des teils französischen (1805-14), teils polnischen Originals (1847)."},{"text":"„Das war's etwa, was ich schreiben würde. Recht gut ineinander verschlungen, ein Ghasel.“","reference":"Knut Hamsun: Im Märchenland. Rütten & Loening, Berlin 1990 (übersetzt von Cläre Greverus Mjoën, Gertrud Ingeborg Klett), ISBN 3-352-00299-1, Seite 109. Norwegisches Original 1903."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghasel","id":"30daa913e88ea6"},"0067-0068:a9bcfb162e81ce":{"word":"Ghadames","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Gha·da·mes","de-DE":"Gha·da·mes"},"forms":[{"form":"gha","tags":["Kurzform"]},{"form":"Ghadames’","tags":["Genitiv","Singular"]},{"form":"des Ghadames","tags":["Genitiv","Singular"]},{"form":"des Ghadames’","tags":["Genitiv","Singular"]},{"form":"(das) Ghadames","tags":["Nominativ","Singular"]},{"form":"(dem) Ghadames","tags":["Dativ","Singular"]}],"senses":[{"definition":"in Libyen gesprochener insulärer Oasendialekt des Tamaschek, der je nach Quelle auch als eigenständige Berbersprache angesehen wird"}],"synonyms":[],"origins":[],"examples":[{"text":"„Mit Kossmann kann man die Berbersprachen in 8 Gruppen einteilen: Touareg, Ghadames und Augila, Kabyl, Chleuh, Berber des Mittleren Atlas, Zenati, östliches sowie mauretanisches Berber.“","reference":"Anja Overbeck,Wolfgang Schweickard,Harald V Lker,Harald Völker: Lexikon, Varietät, Philologie: Romanistische Studien Günter Holtus zum 65. Geburtstag. De Gruyter, 2011, ISBN 978-3110262285 , Seite 104"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghadames","id":"a9bcfb162e81ce"},"0067-0068:81d6b1e3ddc48f":{"word":"Ghadames","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Gha·da·mes","de-DE":"Gha·da·mes"},"forms":[{"form":"Ghadames’","tags":["Genitiv","Singular"]},{"form":"des Ghadames","tags":["Genitiv","Singular"]},{"form":"(das) Ghadames","tags":["Nominativ","Singular"]},{"form":"(dem) Ghadames","tags":["Dativ","Singular"]}],"senses":[{"definition":"Oasenstadt im westlichen Libyen"}],"synonyms":[],"origins":[],"examples":[{"text":"„Die Wissenschaftler folgten in einer Flughöhe von 300 Metern der nördlichen Karawanenstraße nach Aïn Salah und Ghadames und drangen bald nach El Juf vor, jene Wüste der goldgelben Dünen, inmitten derer das betroffene Gebiet angeblich liegen sollte.“","reference":"Clark Ashton Smith: Invasion von der Venus. In: Das Labyrinth des Maal Dweb. Festa, Leipzig 2013, ISBN 978-3-86552-128-6, Seite 290 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghadames","id":"81d6b1e3ddc48f"},"0067-0068:a7fe014bb3befc":{"word":"Ghzg.","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"Ghz·g.","de-DE":"Ghz·g."},"forms":[],"senses":[{"definition":"Großherzog"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghzg.","id":"a7fe014bb3befc"},"0067-0068:b9431060dbe733":{"word":"Ghzgt.","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"Ghzgt.","de-DE":"Ghzgt."},"forms":[],"senses":[{"definition":"Großherzogtum"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghzgt.","id":"b9431060dbe733"},"0067-0068:008de55310ad10":{"word":"Ghee","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ghee","de-DE":"Ghee"},"forms":[{"form":"Ghi","tags":["variant"]},{"form":"Ghee","tags":["Nominativ","Singular"]}],"senses":[{"definition":"in der indischen Küche verwendetes, aus Büffelmilch oder Kuhmilch gewonnenes, gereinigtes Butterfett"}],"synonyms":[],"origins":["Lehnwort aus dem Englischen vom Substantiv ghee ^(→ en) zu Hindi घी (ghi) ^(→ hi), das auf Sanskrit घृत (ghṛtá) ^(→ sa) „gereinigte Butter“ zurückgeht."],"examples":[{"text":"Zunächst erhitzt er Ghee, ohne zu verraten, was das ist (geklärtes Butterfett aus der indischen Küche nämlich).","reference":"von Siebeck: Falscher Hahn. Kochwettbewerb (2). In: Zeit Online. Nummer 38/2005, 15. September 2005, ISSN 0044-2070 (URL, abgerufen am 5. September 2014) ."},{"text":"Auf einer Art Empore gießen grauhaarige Ministrantinnen in weißen Gewändern heiliges Ghee auf blütenbekränzte Lingamsteine.","reference":"Erhard Hobert: Die zwei Gesichter Kalis. In: Zeit Online. Nummer 47/1988, 18. November 1988, ISSN 0044-2070 (URL, abgerufen am 5. September 2014) ."},{"text":"An der Grazer Universitäts-Augenklinik wurde die Wirksamkeit des Augenbades mit Ghee beim sogenannten Sicca-Syndrom erstmals wissenschaftlich überprüft.","reference":"Claudia Richter: Ayurveda: „Unschlagbar bei chronischen Krankheiten“. In: DiePresse.com. 9. November 2008, ISSN 1563-5449 (URL, abgerufen am 6. September 2014) ."},{"text":"Laut ayurvedischer Medizin soll er die Samenproduktion anregen, und in Asien schwört man auf Spargelwurzeln, die mit Ghee (Butterschmalz) und Milch gekocht werden.","reference":"Claudia Richter: Spargel: Gut für Gedächtnis und Gesicht. In: DiePresse.com. 13. April 2013, ISSN 1563-5449 (URL, abgerufen am 6. September 2014) ."},{"text":"Zum Frühstück hat er gewürzte ayurvedische Cerealien mit Trockenfrüchten gegessen, die mit Ghee und Wasser gekocht werden.","reference":"Viktoria Großmann: Einmal auf null, bitte. Ayurveda-Koch Alexander Linder. In: sueddeutsche.de. 16. Juni 2010, ISSN 0174-4917 (URL, abgerufen am 6. September 2014) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghee","id":"008de55310ad10"},"0067-0068:524c950e2e7fc5":{"word":"GHz","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"GHz","de-DE":"GHz"},"forms":[{"form":"㎓","tags":["alternative"]}],"senses":[{"definition":"Gigahertz"}],"synonyms":[],"origins":[],"examples":[{"text":"Mein Prozessor hat 3 GHz.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"GHz","id":"524c950e2e7fc5"},"0067-0068:435de41484de64":{"word":"Ghettokind","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ghet·to·kind","de-DE":"Ghet·to·kind"},"forms":[{"form":"Ghettokind","tags":["Nominativ","Singular"]},{"form":"Ghettokinde","tags":["Dativ","Singular"]},{"form":"Ghettokinds","tags":["Genitiv","Singular"]},{"form":"Ghettokinder","tags":["Nominativ","Plural"]},{"form":"Ghettokindes","tags":["Genitiv","Singular"]},{"form":"Ghettokindern","tags":["Dativ","Plural"]}],"senses":[{"definition":"Kind, das in einem Ghetto aufwächst/aufgewachsen ist"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Ghetto und Kind"],"examples":[{"text":"„In mehr formalen Situationen, wie im Interview, in dem der Sprecher systematisch beobachtet wird und die Aufmerksamkeit auf die Sprache gerichtet ist, können Ghettokinder, wie Labov (1969) zeigt, sehr einsilbig sein.“","reference":"Els Oksaar: Spracherwerb im Vorschulalter. Einführung in die Pädolinguistik. Kohlhammer, Stuttgart/Berlin/Köln/Mainz 1977, ISBN 3-17-004471-0, Seite 114."},{"text":"„Labov sieht eine direkte Verbindung von Bernsteins Auffassung, die durch starke Parteilichkeit gegen alle Sprachformen der Unterschicht gekennzeichnet sei, zu dem ‚kumulativen Defizit‘ von Deutsch und den Sprachprogrammen von Bereiter/Engelmann, die Ghettokindern Zugang zu gesellschaftlichen Rechten und Privilegien über mittelschichtorientierten Patterndrill eröffnen wollen.“","reference":"Wolfgang Klein, Dieter Wunderlich, unter Mitarbeit von Norbert Dittmar (Herausgeber): Aspekte der Soziolinguistik. Athenäum, Frankfurt/Main 1971, Seite 80. Zitat aus einem Begleittext, den Norbert Dittmar zu einem gekürzten Artikel von William Labov verfasst hat."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghettokind","id":"435de41484de64"},"0067-0068:65f64aa8e621dc":{"word":"Ghostwriterin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ghost·wri·te·rin","de-DE":"Ghost·wri·te·rin"},"forms":[{"form":"Ghostwriter","tags":["masculine"]},{"form":"Ghostwriterin","tags":["Nominativ","Singular"]},{"form":"Ghostwriterinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"weibliche Person, die für jemand anderen Texte verfasst, aber als Autorin nicht genannt wird"}],"synonyms":[],"origins":["Ableitung (Motion, Movierung) des Femininums aus der männlichen Form Ghostwriter mit dem Derivatem (Ableitungsmorphem) -in"],"examples":[{"text":"„Bevor ich antworten konnte, fragte er mich, womit ich jetzt mein Geld verdiene, und ich erzählte ihm von meinen Aufträgen als Ghostwriterin eines Ghostwriters.“","reference":"Nava Ebrahimi: Sechzehn Wörter. Roman. btb, München 2019, ISBN 978-3-442-71754-5 , Seite 169."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghostwriterin","id":"65f64aa8e621dc"},"0067-0068:1602edadf192ba":{"word":"Ghule","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ghu·le","de-DE":"Ghu·le"},"forms":[{"form":"Ghul","tags":["variant"]},{"form":"Ghula","tags":["variant"]},{"form":"Ghule","tags":["Nominativ","Singular"]},{"form":"Ghûle","tags":["alternative","archaic"]},{"form":"Ghūle","tags":["alternative"]},{"form":"Rhula","tags":["variant","archaic"]},{"form":"Ghulen","tags":["Nominativ","Plural"]},{"form":"Ghulin","tags":["variant"]}],"senses":[{"definition":"Ghul in Gestalt einer (hübschen, verführerischen) Frau, eines Mädchens"}],"synonyms":[],"origins":["weibliche Form zu Ghul"],"examples":[{"text":"„In den Märchen der 1001 Nacht zeigt sich die Ghule als schöne, junge Frau, die erst in der Nacht, nachdem sie ihrem Gatten einen Schlaftrunk beigebracht hat, ihre wirkliche Gestalt annimmt; oder sie erscheint dem einsamen Reitersmann in der Wüste als ein junges Mädchen, das weinend am Wege sitzt und ihn flehentlich bittet, sie mitzunehmen. Er lässt sie mitleidig hinter sich aufsitzen und erkennt sie erst später als Menschenfresserin.“","reference":"Alfred Freiherr v. Kremer: Ⅷ. Studien zur vergleichenden Culturgeschichte, vorzüglich nach arabischen Quellen. Ⅲ. Götter und Geister im arabischen Volksglauben. In: Sitzungsberichte der Philosophisch-Historischen Classe der Kaiserlichen Akademie der Wissenschaften. Hundertzwanzigster Band, in Commission bei F. Tempsky, Wien 1890, Seite 55 (Zitiert nach Google Books) ."},{"text":"„So ist die junge Gräfin eine Ghule, der Brillenhändler ein Magier und die Stiftsdame eine Fee.“","reference":"Gabrielle Wittkop-Ménardeau: E. T. A. Hoffmann in Selbstzeugnissen und Bilddokumenten. Rowohlt, Reinbek bei Hamburg 1966, ISBN 3-499-50113-9, Seite 41 ."},{"text":"„In der sicher zu den kunstvollsten Erzählungen Hoffmanns gehörenden Vampir-Geschichte (seltsamerweise wird sie von der Sekundärliteratur kaum beachtet), in der vordergründig die langsame Verwandlung eines jungen Mädchens in eine leichenfressende Ghule gezeigt wird, die Anzeichen für ihre Verwandlung jedoch durch typische Merkmale eines blutsaugendes Vampirs gegeben werden, scheinen ausschlaggebend für Aureliens Verwandlung: […]“","reference":"Gisela Köhler: Narzissmus, übersinnliche Phänomene und Kindheitstrauma im Werk E. T. A. Hoffmanns. Johann Wolfgang Goethe-Universität zu Frankfurt am Main, 1971, Seite 303 (Zitiert nach Google Books) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghule","id":"1602edadf192ba"},"0067-0068:f16d12904bae10":{"word":"Ghul","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ghul","de-DE":"Ghul"},"forms":[{"form":"Ghul","tags":["feminine"]},{"form":"Ghûl","tags":["alternative","archaic"]},{"form":"Ghūl","tags":["alternative"]},{"form":"Ghula","tags":["feminine"]},{"form":"Ghule","tags":["feminine"]},{"form":"Ghuls","tags":["Genitiv","Singular"]},{"form":"Ghulen","tags":["Dativ","Plural"]},{"form":"Ghulin","tags":["feminine"]}],"senses":[{"definition":"(im muslimisch-orientalischen Kontext) zu den Dschinn gehörendes dämonenhaftes Fabelwesen, das unterschiedliche (vor allem menschliche) Gestalten annimmt und das Reisende an abgelegenen, ansonsten unbewohnten Orten (vor allem in der Wüste) irreführt und sie so in den sicheren Tod schickt (nach europäischer Hinzudeutung ab dem 18. Jahrhundert tötet es Menschen an diesen abgelegenen Orten aktiv und verschlingt ihre Leichen oder, wenn es auf keine lebendigen Menschen trifft, treibt es vor allem auf Friedhöfen als Grabräuber und Leichenfresser sein Unwesen)"}],"synonyms":[],"origins":["Das Wort ist dem gleichbedeutend arabischen غُول (DMG: ġūl)^(→ar) entlehnt (vergleiche Algol)."],"examples":[{"text":"„Abd Hajjāf, Indiens Heldenkönig, erlegt einen Ghūl mit einem Hieb, der Ghūl bittet, er möge noch ein zweites Mal nach ihm hauen, Abd Hajjāf hütet sich wohl davor und verkündet auch in einem Gedichte dieses Grundgesetz der Dämonentödtung: den Hieb nicht wiederholen ([…]).“","reference":"Bernhard Heller: DIE BEDEUTUNG DES ARABISCHEN ‘ANTAR-ROMANS FÜR DIE VERGLEICHENDE LITTERATURKUNDE. Hermann Eichblatt Verlag, Leipzig 1931, Seite 51 (Zitiert nach Google Books) ."},{"text":"„Da Soraya befürchtete, daß der Ghul sie nun bald einhole, öffnete sie den Seelenkasten, in dem sie einen kleinen Vogel fand. Sie nahm ihn und begann ihm den Hals umzudrehen. Da stieß der Ghul einen fürchterlichen Schrei aus und stürzte auf Soraya zu, um seine Seele aus ihren Händen zu befreien. Sie erwürgte den Vogel. Der Ghul schrie, daß es durch die ganze Wüste hallte, und fiel tot um.“","reference":"Ursula Assaf-Nowak, Yussuf Assaf (Herausgeber): 13. Soraya, die Tochter des Ghul, und die schwarze Hündin. In: Märchen aus dem Libanon. Diederichs, Düsseldorf/Köln 1978 (übersetzt von den Herausgebern aus dem Arabischen), ISBN 3-424-00611-4 (Halbleineneinband), ISBN 3-424-00612-2 (Ledereinband), Seite 122 (Zitiert nach Google Books) ."},{"text":"„Er lief und lief, überstieg Gebirge, durchquerte Wüsten und unwirtliche Wadis, bis er schließlich ins Land der Schrecken und der Ghule gelangte.“","reference":"Sylvia M. Patsch: AUFGELESENES. In: Vorarlberger Nachrichten. 17. Juni 2000, Seite D8 ."},{"text":"„Die Tiere und Pflanzen waren gestorben, alles, was lebte und umging, außer den Ghulen und Geistern der Finsternis.“","reference":"Christine Wunnicke: Die Dame mit der bemalten Hand. Roman. 7. Auflage. Berenberg Verlag, Berlin 2020, ISBN 978-3-946334-76-7, Seite 108 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghul","id":"f16d12904bae10"},"0067-0068:0c04e6fb605243":{"word":"Ghettofaust","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ghet·to·faust","de-DE":"Ghet·to·faust"},"forms":[{"form":"Gettofaust","tags":["alternative"]},{"form":"Getto-Faust","tags":["alternative"]},{"form":"Ghettofaust","tags":["Nominativ","Singular"]},{"form":"Ghetto-Faust","tags":["alternative"]},{"form":"Ghettofäuste","tags":["Nominativ","Plural"]},{"form":"Ghettofäusten","tags":["Dativ","Plural"]}],"senses":[{"definition":"informelle Geste zur Begrüßung, bei der zwei Personen ihre Fäuste kurz gegeneinanderdrücken"}],"synonyms":["Faustcheck","Faustgruß"],"origins":["etymologisch:","Das Wort wurde zunächst in der Jugendsprache verwendet. Es ist belegt seit den 2010er Jahren. Womöglich handelt es sich auch um eine Lehnübertragung von englisch fist bump ^(→ en) (vergleiche Fistbump)","strukturell:","Determinativkompositum aus Ghetto und Faust"],"examples":[{"text":"In der Pandemie hat sich auch bei geschäftlichen Begegnungen die Ghettofaust zur Begrüßung durchgesetzt.","reference":"Detlef Fechtner: Vertragsabschluss per Ghettofaust. In: Boersen-Zeitung.de. 11. Februar 2022, abgerufen am 4. März 2022."},{"text":"„Zur Begrüßung hat Merkel mir eine Ghettofaust gegeben.“","reference":"„Zur Begrüßung hat Merkel mir eine Ghettofaust gegeben“. In: Welt.de. 22. Januar 2022, abgerufen am 4. März 2022."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ghettofaust","id":"0c04e6fb605243"},"0067-0068:8f3caccdb8e333":{"word":"Ghetto-Faust","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ghet·to-Faust","de-DE":"Ghet·to-Faust"},"forms":[{"form":"Gettofaust","tags":["alternative"]},{"form":"Getto-Faust","tags":["alternative"]},{"form":"Ghettofaust","tags":["alternative"]},{"form":"Ghetto-Faust","tags":["Nominativ","Singular"]},{"form":"Ghetto-Fäuste","tags":["Nominativ","Plural"]},{"form":"Ghetto-Fäusten","tags":["Dativ","Plural"]}],"senses":[{"definition":"informelle Geste zur Begrüßung, bei der zwei Personen ihre Fäuste kurz gegeneinanderdrücken"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghetto-Faust","id":"8f3caccdb8e333"},"0067-0068:da11afd69decd4":{"word":"ghosten","partOfSpeech":"Verb","gender":"","hyphenation":{"de-CH":"ghos·ten","de-DE":"ghos·ten"},"forms":[{"form":"haben","tags":["Hilfsverb","Perfekt"]},{"form":"ghost!","tags":["Imperativ","2. Person","Singular","Präsens","Aktiv"]},{"form":"ghoste","tags":["Präsens"]},{"form":"ghoste!","tags":["Imperativ","Singular"]},{"form":"ghosten","tags":["Aktiv","Infinitiv","Präsens"]},{"form":"ghostet","tags":["Präsens"]},{"form":"ghostend","tags":["Partizip","Präsens","Aktiv"]},{"form":"ghostest","tags":["Präsens"]},{"form":"ghostet!","tags":["Imperativ","Plural"]},{"form":"ghostete","tags":["Präteritum"]},{"form":"geghostet","tags":["Partizip II","Perfekt"]},{"form":"ich ghoste","tags":["1. Person","Singular","Präsens","Aktiv","Indikativ"]},{"form":"zu ghosten","tags":["Aktiv","erweitert","Infinitiv"]},{"form":"du ghostest","tags":["2. Person","Singular","Präsens","Aktiv","Indikativ"]},{"form":"ihr ghostet","tags":["2. Person","Plural","Präsens","Aktiv","Indikativ"]},{"form":"sie ghosten","tags":["3. Person","Plural","Präsens","Aktiv","Indikativ"]},{"form":"wir ghosten","tags":["1. Person","Plural","Präsens","Aktiv","Indikativ"]},{"form":"ghosten Sie!","tags":["Imperativ","Höflichkeitsform","Präsens","Aktiv"]},{"form":"ich ghostete","tags":["1. Person","Singular","Präteritum","Aktiv","Indikativ"]},{"form":"zu ghostende","tags":["Partizip","gerundive"]},{"form":"du ghostetest","tags":["2. Person","Singular","Präteritum","Aktiv","Indikativ"]},{"form":"ihr ghostetet","tags":["2. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"sie ghosteten","tags":["3. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"wir ghosteten","tags":["1. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"zu ghostender","tags":["Partizip","gerundive"]},{"form":"geghostet sein","tags":["statal-passive","Infinitiv","Präsens"]},{"form":"sei geghostet!","tags":["Imperativ","uncommon","2. Person","Singular","Präsens","statal-passive"]},{"form":"geghostet haben","tags":["Aktiv","Infinitiv","Perfekt"]},{"form":"habe geghostet!","tags":["Imperativ","uncommon","2. Person","Singular","Perfekt","Aktiv"]},{"form":"habt geghostet!","tags":["Imperativ","uncommon","2. Person","Plural","Perfekt","Aktiv"]},{"form":"seid geghostet!","tags":["Imperativ","uncommon","2. Person","Plural","Präsens","statal-passive"]},{"form":"zu ghostendes …","tags":["Partizip","gerundive"]},{"form":"du wirst ghosten","tags":["2. Person","Singular","Futur I","Aktiv","Indikativ"]},{"form":"er/sie/es ghoste","tags":["3. Person","Singular","Präsens","Aktiv","Konjunktiv I"]},{"form":"geghostet werden","tags":["Vorgangspassiv","Infinitiv","Präsens"]},{"form":"werde geghostet!","tags":["Imperativ","uncommon","2. Person","Singular","Präsens","Vorgangspassiv"]},{"form":"du bist geghostet","tags":["2. Person","Singular","Präsens","statal-passive","Indikativ"]},{"form":"du hast geghostet","tags":["2. Person","Singular","Perfekt","Aktiv","Indikativ"]},{"form":"er/sie/es ghostet","tags":["3. Person","Singular","Präsens","Aktiv","Indikativ"]},{"form":"geghostet zu sein","tags":["statal-passive","erweitert","Infinitiv"]}],"senses":[{"definition":"sich (plötzlich, von einem Tag auf den anderen) zurückziehen und nicht mehr auf Ansprache reagieren"}],"synonyms":[],"origins":["Neologismus zum englischen to ghost ^(→ en), von ghost ^(→ en) Geist"],"examples":[{"text":"„Verliert Ihr Dating-Partner das Interesse an Ihnen, kann es schnell dazu kommen, dass er Sie ‚ghostet‘.“","reference":"Roxana Münster: Was ist ghosten? Abgerufen am 11. Januar 2022."},{"text":"„»Es wäre ziemlich unangenehm, mich mit einer anzustarren, die ich geghostet habe.« »Geghostet?« Er legt die Stirn in Falten und sucht nach einer Erklärung. »Stell dir vor, du hast nicht den Mumm jemandem zu sagen, dass es vorbei ist, […].«“","reference":"Fehlender Parameter (Hilfe) Josie Silver: Abgerufen am 11. Januar 2022."},{"text":"„‚Ich habe dir eine SMS geschickt, um dich nach der Adresse der Bar zu fragen, aber du hast mich geghostet.‘ ‚Ich habe dich nicht geghostet.‘ Ich halte inne und ziehe mein Handy aus meiner Handtasche. Es ist tot.“","reference":"Fehlender Parameter (Hilfe) Kylie Gilmore: Abgerufen am 11. Januar 2022."}],"idioms":[],"collocations":[],"derivations":["Geghosteter","Ghosting"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"ghosten","id":"da11afd69decd4"},"0067-0068:6331d8742b8e3b":{"word":"Ghuride","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ghu·r·i·de","de-DE":"Ghu·r·i·de"},"forms":[{"form":"Guride","tags":["variant"]},{"form":"Ghoride","tags":["variant"]},{"form":"Ghuride","tags":["Nominativ","Singular"]},{"form":"Ghuriden","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Angehöriger der gleichnamigen Dynastie in Zentral- und Südasien"}],"synonyms":[],"origins":[],"examples":[{"text":"Die Ghuriden waren große Förderer der persischen Sprache und Kultur.","reference":""},{"text":"„In der ersten Hälfte des 12. Jahrhunderts beerbten die Ghuriden das Ghaznavidenreich.“","reference":"Katja Mielke/Conrad Schetter: Pakistan: Land der Extreme. 1. Auflage. C.H.Beck, München 2013, ISBN 978-3-406-65295-0, Seite 47 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghuride","id":"6331d8742b8e3b"},"0067-0068:501a3f8a64b74e":{"word":"Ghaznawide","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ghaz·na·wi·de","de-DE":"Ghaz·na·wi·de"},"forms":[{"form":"Ghaznavide","tags":["variant"]},{"form":"Ghaznawide","tags":["Nominativ","Singular"]},{"form":"Ghaznawiden","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Angehöriger der gleichnamigen Dynastie in Zentral- und Südasien"}],"synonyms":[],"origins":[],"examples":[{"text":"„Jedoch konnten sich die Ghaznawiden der zunehmend mächtiger werdenden Seldschuken kaum noch erwehren.“","reference":"Conrad Schetter: Kleine Geschichte Afghanistans. 5. Auflage. C.H.Beck, München 2022, ISBN 978-3-406-78487-3, Seite 40 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghaznawide","id":"501a3f8a64b74e"},"0067-0068:af737e3b0800b3":{"word":"Ghoride","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Gho·ri·de","de-DE":"Gho·ri·de"},"forms":[{"form":"Ghoride","tags":["Nominativ","Singular"]},{"form":"Ghoriden","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Angehöriger der gleichnamigen Dynastie in Zentral- und Südasien"}],"synonyms":[],"origins":[],"examples":[{"text":"„Erst sein fähiger Heerführer, der Sklave Qutbuddin Aibak, der bei Mohammads Tod den Ghoriden die Gefolgschaft aufsagte, entschied sich für Indien und errichtete 1206 das Sultanat von Delhi, um die Unabhängigkeit von seinen einstigen Herren zu erringen.“","reference":"Dietmar Rothermund: Geschichte Indiens. Vom Mittelalter bis zur Gegenwart. 3. Auflage. C.H.Beck, München 2010, ISBN 978-3-406-47994-6, Seite 27 ."},{"text":"„Den endgültigen Niedergang der Ghaznawiden besiegelten die Ghoriden, benannt nach einer gebirgigen Region östlich Herats.“","reference":"Conrad Schetter: Kleine Geschichte Afghanistans. 5. Auflage. C.H.Beck, München 2022, ISBN 978-3-406-78487-3, Seite 41 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghoride","id":"af737e3b0800b3"},"0067-0068:ae9525f30d7847":{"word":"Ghaznavide","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ghaz·na·vi·de","de-DE":"Ghaz·na·vi·de"},"forms":[{"form":"Ghaznavide","tags":["Nominativ","Singular"]},{"form":"Ghaznaviden","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Angehöriger der gleichnamigen Dynastie in Zentral- und Südasien"}],"synonyms":[],"origins":[],"examples":[{"text":"„Dieses Mal kamen die Eroberer von Norden her. Es waren vor allem die Ghaznaviden, die nach ihrer Hauptstadt Ghazni im heutigen Afghanistan benannt sind.“","reference":"Katja Mielke/Conrad Schetter: Pakistan: Land der Extreme. 1. Auflage. C.H.Beck, München 2013, ISBN 978-3-406-65295-0, Seite 47 ."},{"text":"„Der koreanische Mönch Hui-Tschao, der 827 in die Stadt kam, schrieb, der König von Bamian sei immer noch Buddhist, und erst im 11. Jahrhundert sollten die Ghaznaviden den Islam im Tal etablieren können.“","reference":"Ahmed Rashid: Taliban. Afghanistans Gotteskämpfer und der neue Krieg am Hindukusch. C.H.Beck, München 2022, ISBN 978-3-406-78467-5, Seite 116 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghaznavide","id":"ae9525f30d7847"},"0067-0068:dfda62de232a64":{"word":"Ghotki","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Ghot·ki","de-DE":"Ghot·ki"},"forms":[{"form":"Ghotkis","tags":["Genitiv","Singular"]},{"form":"des Ghotki","tags":["Genitiv","Singular"]},{"form":"des Ghotkis","tags":["Genitiv","Singular"]},{"form":"(das) Ghotki","tags":["Nominativ","Singular"]},{"form":"(dem) Ghotki","tags":["Dativ","Singular"]}],"senses":[{"definition":"Stadt in der pakistanischen Provinz Sindh"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghotki","id":"dfda62de232a64"},"0067-0068:bd14d8a45eb9eb":{"word":"Ghazni","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Ghaz·ni","de-DE":"Ghaz·ni"},"forms":[{"form":"Ghaznis","tags":["Genitiv","Singular"]},{"form":"des Ghazni","tags":["Genitiv","Singular"]},{"form":"des Ghaznis","tags":["Genitiv","Singular"]},{"form":"(das) Ghazni","tags":["Nominativ","Singular"]},{"form":"(dem) Ghazni","tags":["Dativ","Singular"]}],"senses":[{"definition":"Stadt in Zentralafghanistan"},{"definition":"afghanische Provinz mit [1] als Hauptstadt"}],"synonyms":[],"origins":[],"examples":[{"text":"„Hier gründete er 962 ein halbautonomes Reich mit Ghazni als Hauptstadt.“","reference":"Conrad Schetter: Kleine Geschichte Afghanistans. 5. Auflage. C.H.Beck, München 2022, ISBN 978-3-406-78487-3, Seite 40 ."},{"text":"„In chinesischen und indischen Quellen aus dem 6. Jahrhundert ist von Afghanen/Paschtunen östlich von Ghazni die Rede.“","reference":"Ahmed Rashid: Taliban. Afghanistans Gotteskämpfer und der neue Krieg am Hindukusch. C.H.Beck, München 2022, ISBN 978-3-406-78467-5, Seite 32 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghazni","id":"bd14d8a45eb9eb"},"0067-0068:5c2482d106cd97":{"word":"Ghaziabad","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Gha·zia·bad","de-DE":"Gha·zia·bad"},"forms":[{"form":"Ghaziabads","tags":["Genitiv","Singular"]},{"form":"des Ghaziabad","tags":["Genitiv","Singular"]},{"form":"des Ghaziabads","tags":["Genitiv","Singular"]},{"form":"(das) Ghaziabad","tags":["Nominativ","Singular"]},{"form":"(dem) Ghaziabad","tags":["Dativ","Singular"]}],"senses":[{"definition":"Stadt im indischen Bundesstaat Uttar Pradesh"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghaziabad","id":"5c2482d106cd97"},"0067-0068:ec9b90827aa946":{"word":"Ghazipur","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Gha·zi·pur","de-DE":"Gha·zi·pur"},"forms":[{"form":"Ghazipurs","tags":["Genitiv","Singular"]},{"form":"des Ghazipur","tags":["Genitiv","Singular"]},{"form":"des Ghazipurs","tags":["Genitiv","Singular"]},{"form":"(das) Ghazipur","tags":["Nominativ","Singular"]},{"form":"(dem) Ghazipur","tags":["Dativ","Singular"]}],"senses":[{"definition":"Stadt im indischen Bundesstaat Uttar Pradesh"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghazipur","id":"ec9b90827aa946"},"0067-0068:2d35b0e39c3357":{"word":"Ghosting","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ghos·ting","de-DE":"Ghos·ting"},"forms":[{"form":"Ghosting","tags":["Nominativ","Singular"]},{"form":"Ghostings","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Verhaltensweise, bei der in einer zwischenmenschlichen Beziehung überraschenderweise und ohne erkennbaren Grund ein völliger Kontaktabbruch erfolgt"}],"synonyms":[],"origins":[],"examples":[{"text":"„Dabei wird zunächst besonders starkes Interesse bekundet, das Blaue vom Himmel versprochen – nur um dann Ghosting zu betreiben und den anderen vollkommen verwirrt zurückzulassen, warum nach so großen Gesten und Liebesschwüren plötzlich der Ofen vollkommen aus ist.“","reference":"Daniela Herger: Ghosting und Co: Welche Hinhaltetaktiken haben Sie erlebt?. In: Der Standard digital. 24. Februar 2023 (URL, abgerufen am 4. März 2024) ."}],"idioms":[],"collocations":[],"derivations":["Ghostingopfer"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghosting","id":"2d35b0e39c3357"},"0067-0068:5a1a6b27b7be85":{"word":"Ghettohaus","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ghet·to·haus","de-DE":"Ghet·to·haus"},"forms":[{"form":"Ghettohaus","tags":["Nominativ","Singular"]},{"form":"Ghettohauses","tags":["Genitiv","Singular"]},{"form":"Ghettohäuser","tags":["Nominativ","Plural"]},{"form":"Ghettohäusern","tags":["Dativ","Plural"]}],"senses":[{"definition":"Haus, das in einem Ghetto liegt"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Ghetto und Haus"],"examples":[{"text":"„Die Tafel verrät alles – Vergangenheit und Gegenwart, verewigt auf weißer Plastikfolie. Man erfährt, wer bei Beziehungstaten mit einem halben Dutzend Angehöriger als Zeugen Speck ansetzen konnte und wer bei einem Drogenmord in einem leer stehenden Ghettohaus ausgehungert wurde.“","reference":"David Simon: Homicide. Ein Jahr auf mörderischen Straßen. Antje Kunstmann, München 2011, ISBN 978-3-888-97723-7, Seite 57 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghettohaus","id":"5a1a6b27b7be85"},"0067-0068:5eb3fbfe3fa3c5":{"word":"Ghawar","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Gha·war","de-DE":"Gha·war"},"forms":[{"form":"Ghawars","tags":["Genitiv","Singular"]},{"form":"des Ghawar","tags":["Genitiv","Singular"]},{"form":"des Ghawars","tags":["Genitiv","Singular"]},{"form":"(das) Ghawar","tags":["Nominativ","Singular"]},{"form":"(dem) Ghawar","tags":["Dativ","Singular"]}],"senses":[{"definition":"größtes bekanntes Ölfeld der Welt in Saudi-Arabien"}],"synonyms":[],"origins":[],"examples":[{"text":"„Sie müssen Hunderte von Milliarden in Ghawar stecken, um es vollständig zu erschließen oder andere Lagerstätten auszubeuten.“","reference":"Ben Coes: Power Down. Festa, Leipzig 2013, ISBN 978-3-865-52236-8, Seite 300 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghawar","id":"5eb3fbfe3fa3c5"},"0067-0068:eaf98c4c5062f3":{"word":"Ghilzai","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ghil·zai","de-DE":"Ghil·zai"},"forms":[{"form":"Ghilzai","tags":["Nominativ","Singular"]},{"form":"Ghilzais","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Angehöriger eines paschtunischen Stammesverbands"}],"synonyms":[],"origins":[],"examples":[{"text":"„Die Stämme der Paschtunen unterteilen sich in der Hauptsache in Ghilzai und Abdali, später Durrani genannt, die miteinander rivalisieren.“","reference":"Ahmed Rashid: Taliban. Afghanistans Gotteskämpfer und der neue Krieg am Hindukusch. C.H.Beck, München 2022, ISBN 978-3-406-78467-5, Seite 32 ."},{"text":"„Mit den Durrani und den Ghilzai entstanden im 18. Jahrhundert zwei miteinander konkurrierende Stammeskonföderationen, die einen Großteil der paschtunischen Stämme vereinen.“","reference":"Conrad Schetter/Katja Mielke: Die Taliban. Geschichte, Politik, Ideologie. C.H.Beck, München 2022, ISBN 978-3-406-78581-8, Seite 15 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghilzai","id":"eaf98c4c5062f3"},"0067-0068:d50e8b3e1cbb9a":{"word":"Ghor","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Ghor","de-DE":"Ghor"},"forms":[{"form":"Ghors","tags":["Genitiv","Singular"]},{"form":"des Ghor","tags":["Genitiv","Singular"]},{"form":"des Ghors","tags":["Genitiv","Singular"]},{"form":"(das) Ghor","tags":["Nominativ","Singular"]},{"form":"(dem) Ghor","tags":["Dativ","Singular"]}],"senses":[{"definition":"Provinz in Zentralafghanistan"}],"synonyms":[],"origins":[],"examples":[{"text":"„Im Juli 1987 hielt Ismael Khan ein erstes Treffen der Feldkommandanten in der Provinz Ghor ab, zu dem ungefähr 1200 Kommandanten aus ganz Afghanistan kamen.“","reference":"Ahmed Rashid: Taliban. Afghanistans Gotteskämpfer und der neue Krieg am Hindukusch. C.H.Beck, München 2022, ISBN 978-3-406-78467-5, Seite 160 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghor","id":"d50e8b3e1cbb9a"},"0067-0068:82e627dd16d50a":{"word":"Ghatkopar","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Ghat·ko·par","de-DE":"Ghat·ko·par"},"forms":[{"form":"Ghatkopars","tags":["Genitiv","Singular"]},{"form":"des Ghatkopar","tags":["Genitiv","Singular"]},{"form":"des Ghatkopars","tags":["Genitiv","Singular"]},{"form":"(das) Ghatkopar","tags":["Nominativ","Singular"]},{"form":"(dem) Ghatkopar","tags":["Dativ","Singular"]}],"senses":[{"definition":"Vorort von Mumbai"}],"synonyms":[],"origins":[],"examples":[{"text":"„Trickbetrügerin erbeutet Schmuck von Hausfrauen in Ghatkopar. Führungsspitze der Kongresspartei dementiert interne Machtkämpfe. Ein Beitrag auf der Titelseite berichtete, wie Gaitonde in seiner langen Laufbahn immer wieder haarscharf entkommen war.“","reference":"Vikram Chandra: Der Pate von Bombay. Aufbau, Berlin 2009, ISBN 978-3-7466-2483-9, Seite 94 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghatkopar","id":"82e627dd16d50a"},"0067-0068:83c1375b817067":{"word":"Ghom","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Ghom","de-DE":"Ghom"},"forms":[{"form":"Ghoms","tags":["Genitiv","Singular"]},{"form":"des Ghom","tags":["Genitiv","Singular"]},{"form":"des Ghoms","tags":["Genitiv","Singular"]},{"form":"(das) Ghom","tags":["Nominativ","Singular"]},{"form":"(dem) Ghom","tags":["Dativ","Singular"]}],"senses":[{"definition":"Stadt im Iran"},{"definition":"iranische Provinz mit [1] als Hauptstadt"}],"synonyms":[],"origins":[],"examples":[{"text":"„Dank der über die Jahrhunderte unterhaltenen Verbindungen konnten sich auch in moderner Zeit libanesische Schiiten bei prominenten schiitischen Geistlichen an den religiösen Universitäten in Nadschaf und Kerbela im Irak und in der Stadt Ghom in Iran ausbilden lassen.“","reference":"Joseph Croitoru: Die Hisbollah. Irans Schattenarmee vor den Toren Israels. C.H.Beck, München 2025, ISBN 978-3-406-82909-3, Seite 22 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghom","id":"83c1375b817067"},"0067-0068:9c47048b14e3d5":{"word":"Ghadschar","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Ghad·schar","de-DE":"Ghad·schar"},"forms":[{"form":"Ghadschars","tags":["Genitiv","Singular"]},{"form":"des Ghadschar","tags":["Genitiv","Singular"]},{"form":"des Ghadschars","tags":["Genitiv","Singular"]},{"form":"(das) Ghadschar","tags":["Nominativ","Singular"]},{"form":"(dem) Ghadschar","tags":["Dativ","Singular"]}],"senses":[{"definition":"Ortschaft zwischen dem Libanon und den Golanhöhen"}],"synonyms":[],"origins":[],"examples":[{"text":"„Entsprechend wurde hier jetzt ihre Miliz (al-muqawama) in einem Atemzug mit dem libanesischen Volk und der Armee genannt, denen der Auftrag zukomme, ›die Schebaa-Farmen, die libanesischen Kafr-Schuba-Hügel und den libanesischen Teil des [geteilten] Dorfes Ghadschar zu befreien oder zurückzugewinnen und den Libanon gegen jeden Angriff sowie sein Recht auf seine Gewässer mit allen legitimen und verfügbaren Mitteln zu verteidigen‹.“","reference":"Joseph Croitoru: Die Hisbollah. Irans Schattenarmee vor den Toren Israels. C.H.Beck, München 2025, ISBN 978-3-406-82909-3, Seite 129 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghadschar","id":"9c47048b14e3d5"},"0067-0068:f561a83d21dd51":{"word":"Ghat","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ghat","de-DE":"Ghat"},"forms":[{"form":"Ghat","tags":["Nominativ","Singular"]},{"form":"Ghats","tags":["Nominativ","Plural"]}],"senses":[{"definition":"zu einem Gewässer hinunterführende Böschung oder Stufung, oft vor hinduistischen Tempeln"}],"synonyms":[],"origins":[],"examples":[{"text":"„Es gab dort alte Bäume, und abends saß Adil gern an den Ghats und blickte zum anderen Ufer hinüber.“","reference":"Vikram Chandra: Der Pate von Bombay. Aufbau, Berlin 2009, ISBN 978-3-7466-2483-9, Seite 1092 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghat","id":"f561a83d21dd51"},"0067-0068:ba5ebe52cdb788":{"word":"Ghats","partOfSpeech":"Toponym","gender":"","hyphenation":{"de-CH":"Ghats","de-DE":"Ghats"},"forms":[{"form":"Ghats","tags":["Nominativ","Plural"]}],"senses":[{"definition":"zwei Gebirgszüge an der Küste Südindiens"}],"synonyms":[],"origins":[],"examples":[{"text":"„Sie machte eine ausladende Geste in Richtung der Ghats und Sartaj begriff, dass sie genauso dringend wie er in die Berge wollte.“","reference":"Vikram Chandra: Der Pate von Bombay. Aufbau, Berlin 2009, ISBN 978-3-7466-2483-9, Seite 673 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ghats","id":"ba5ebe52cdb788"}};
